/// Whether Planning's tab is the one selected.
fn on_planning_tab(&self) -> bool {
    self.selected_file
        .and_then(|ix| self.files.get(ix))
        .is_some_and(|tab| matches!(tab, BodyTab::Planning(_)))
}

